function readFileSync(...args) {
  const value = readFileSyncRaw(...args);
  return typeof value === 'string' ? value.replace(/\r\n/g, '\n') : value;
}

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function assertEqual(actual, expected, message) {
  if (actual !== expected) throw new Error(`${message} Expected ${expected}, got ${actual}.`);
}

function disabledGateway() {
  return {
    hasConfiguredKey: () => false,
    complete: async () => {
      throw new Error('Disabled AI Gateway should not be called in deterministic rule tests.');
    }
  };
}

function makeBlueprint(overrides = {}) {
  return {
    id: 42,
    subject: 'math',
    topicId: 7,
    topicCode: 'M-FUN-001',
    topicModule: 'Algebra',
    topicTitle: 'Functions',
    syllabusVersion: '2026',
    examScope: 'Evaluate and interpret linear functions within the CSCA algebra scope.',
    allowedQuestionTypes: ['single_choice'],
    difficultyRange: ['基础', '中等'],
    sourceLabel: 'CSCA Math 2026',
    sourceUrl: 'https://example.edu/csca/math-2026',
    difficulty: '基础',
    questionType: 'single_choice',
    skill: 'linear functions',
    constraints: { roundSize: 5 },
    ...overrides
  };
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function countOccurrences(source, needle) {
  return source.split(needle).length - 1;
}

function expectThrows(fn, expectedText, message) {
  try {
    fn();
  } catch (error) {
    const text = String(error?.message ?? error);
    assert(text.includes(expectedText), `${message} Expected error to include "${expectedText}", got "${text}".`);
    return;
  }
  throw new Error(`${message} Expected function to throw.`);
}

function makeSyllabusImportPayload(overrides = {}) {
  return {
    schemaVersion: 'csca-syllabus-v1',
    subject: 'math',
    syllabusVersion: '2026-v1',
    sourceLabel: 'Official CSCA Math Syllabus 2026',
    sourceUrl: 'https://example.edu/csca/math-2026',
    verifiedAt: '2026-06-11T00:00:00.000Z',
    topics: [
      {
        code: 'M-ALG-001',
        title: 'Linear equations',
        module: 'Algebra',
        examScope: 'Solve one-variable linear equations and interpret simple word problems.',
        allowedQuestionTypes: ['single_choice'],
        difficultyRange: ['basic', 'medium', 'hard'],
        weight: 3,
        skills: ['solve', 'interpret'],
        aliases: ['one-variable equations'],
        excludedScope: ['quadratic equations'],
        status: 'published'
      }
    ],
    ...overrides
  };
}

function testSyllabusImportPayloadValidation() {
  const normalized = validateCscaSyllabusImportPayload(makeSyllabusImportPayload());
  assertEqual(normalized.subject, 'math', 'Syllabus import should preserve subject.');
  assertEqual(normalized.syllabusVersion, '2026-v1', 'Syllabus import should preserve version.');
  assertEqual(normalized.topics.length, 1, 'Syllabus import should preserve topics.');
  assertEqual(normalized.topics[0].code, 'M-ALG-001', 'Syllabus topic code should normalize.');
  assertEqual(normalized.topics[0].weight, 3, 'Syllabus topic weight should normalize.');
  assertEqual(normalized.topics[0].allowedQuestionTypes[0], 'single_choice', 'Syllabus topic question type should normalize.');
  assertEqual(normalized.topics[0].difficultyRange.join(','), 'basic,medium,hard', 'Syllabus import should preserve the full basic/medium/hard difficulty range.');
  const normalizedWithPreviousCodes = validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
    topics: [{ ...makeSyllabusImportPayload().topics[0], previousCodes: ['M-OLD-001'] }]
  }));
  assertEqual(normalizedWithPreviousCodes.topics[0].previousCodes[0], 'M-OLD-001', 'Syllabus import should preserve previous code mappings.');
  const template = cscaSyllabusImportTemplate('physics');
  const normalizedTemplate = validateCscaSyllabusImportPayload(template);
  assertEqual(normalizedTemplate.subject, 'physics', 'Syllabus import template should validate for the requested subject.');
  assertEqual(normalizedTemplate.topics[0].difficultyRange.join(','), 'basic,medium,hard', 'Syllabus import template should cover all default production difficulties.');

  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ schemaVersion: 'bad' })),
    'schemaVersion',
    'Syllabus import must reject unknown schema versions.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ subject: 'biology' })),
    'subject',
    'Syllabus import must reject unsupported subjects.'
  );
  const previousSmokeSubjectFlag = process.env.CSCA_ALLOW_SMOKE_SUBJECTS;
  try {
    delete process.env.CSCA_ALLOW_SMOKE_SUBJECTS;
    expectThrows(
      () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ subject: 'smoke_math_123' })),
      'subject',
      'Syllabus import must reject smoke subjects unless the smoke flag is explicit.'
    );
    process.env.CSCA_ALLOW_SMOKE_SUBJECTS = 'true';
    const normalizedSmokeSubject = validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ subject: 'smoke_math_123' }));
    assertEqual(normalizedSmokeSubject.subject, 'smoke_math_123', 'Smoke subject isolation should be available only for smoke tests.');
  } finally {
    if (previousSmokeSubjectFlag === undefined) delete process.env.CSCA_ALLOW_SMOKE_SUBJECTS;
    else process.env.CSCA_ALLOW_SMOKE_SUBJECTS = previousSmokeSubjectFlag;
  }
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ topics: [] })),
    'topics',
    'Syllabus import must reject empty topic lists.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [
        makeSyllabusImportPayload().topics[0],
        { ...makeSyllabusImportPayload().topics[0], title: 'Duplicate code' }
      ]
    })),
    '重复 code',
    'Syllabus import must reject duplicate topic codes.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], examScope: '' }]
    })),
    'examScope',
    'Syllabus import must require exam scope for generation alignment.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({ sourceUrl: 'file:///tmp/syllabus.json' })),
    '来源链接',
    'Syllabus import must reject non-HTTP source URLs.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], code: 'bad code' }]
    })),
    'code 格式',
    'Syllabus import must reject invalid topic code format.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], allowedQuestionTypes: ['essay'] }]
    })),
    '不支持题型',
    'Syllabus import must reject unsupported question types.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], difficultyRange: ['basic', 'impossible'] }]
    })),
    '不支持难度',
    'Syllabus import must reject unsupported difficulty labels.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], previousCodes: ['bad code'] }]
    })),
    'previousCodes',
    'Syllabus import must reject invalid previous topic codes.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [
        { ...makeSyllabusImportPayload().topics[0], previousCodes: ['M-OLD-001'] },
        { ...makeSyllabusImportPayload().topics[0], code: 'M-ALG-002', title: 'Second topic', previousCodes: ['M-OLD-001'] }
      ]
    })),
    '重复旧 code',
    'Syllabus import must reject duplicate previous topic code mappings.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [
        { ...makeSyllabusImportPayload().topics[0], previousCodes: ['M-ALG-002'] },
        { ...makeSyllabusImportPayload().topics[0], code: 'M-ALG-002', title: 'Second topic' }
      ]
    })),
    '本文件中的新 code',
    'Syllabus import must reject previous codes that point to new codes in the same file.'
  );
  expectThrows(
    () => validateCscaSyllabusImportPayload(makeSyllabusImportPayload({
      topics: [{ ...makeSyllabusImportPayload().topics[0], excludedScope: ['linear equations'] }]
    })),
    'excludedScope',
    'Syllabus import must reject excluded scope that conflicts with the topic scope.'
  );
}

function testSourceQuestionProfileNormalizer() {
  const profile = normalizeSourceQuestionAnalysis({
    analysis: {
      schemaVersion: 'source-question-analysis-v2',
      profile: {
        schemaVersion: 'source-question-profile-v2',
        questionForm: 'scenario_application',
        cognitiveSkill: 'application',
        difficultyBand: 'medium',
        readingLoad: 'medium',
        calculationLoad: 'light',
        estimatedTimeSeconds: 75,
        optionPattern: {
          optionStyle: 'numeric',
          distractorTypes: ['unit_conversion_error'],
          commonMisconceptions: ['uses_celsius_instead_of_kelvin']
        }
      }
    },
    sourceQuestion: {
      id: 1,
      subject: 'physics',
      syllabusVersion: '2025',
      topicId: 2,
      promptText: 'A gas sample is heated from 27 C to 127 C at constant pressure. Which volume relation is correct?',
      options: [{ id: 'A', text: 'V doubles' }, { id: 'B', text: 'V increases by 4/3' }]
    }
  });
  assertEqual(profile.schemaVersion, 'source-question-profile-v2', 'Source profile normalizer should emit v2 schema.');
  assertEqual(profile.subject, 'physics', 'Source profile normalizer should preserve subject.');
  assert(profile.topicIds.includes(2), 'Source profile normalizer should include source topic id.');
  assertEqual(profile.questionForm, 'scenario_application', 'Source profile normalizer should prefer v2 profile question form.');
  assertEqual(profile.readingLoad, 'medium', 'Source profile normalizer should preserve v2 reading load.');
  assertEqual(profile.calculationLoad, 'light', 'Source profile normalizer should preserve v2 calculation load.');
  assertEqual(profile.optionPattern.distractorTypes[0], 'unit_conversion_error', 'Source profile normalizer should preserve distractor types.');

  const legacyProfile = normalizeSourceQuestionAnalysis({
    analysis: {
      questionForm: 'formula_calculation',
      cognitiveSkill: 'calculation',
      difficulty: 'basic',
      calculationLoad: 'light',
      stemPattern: { length: 'low' },
      reasoningSteps: 1
    },
    sourceQuestion: {
      subject: 'math',
      syllabusVersion: '2025',
      topicId: 3,
      promptText: 'Calculate 2 + 3.',
      options: [{ id: 'A', text: '5' }, { id: 'B', text: '6' }]
    }
  });
  assertEqual(legacyProfile.questionForm, 'formula_calculation', 'Source profile normalizer should read legacy question form.');
  assertEqual(legacyProfile.readingLoad, 'low', 'Source profile normalizer should map legacy stemPattern.length to readingLoad.');
  assertEqual(legacyProfile.stemPattern.textLengthBand, 'short', 'Source profile normalizer should keep text length separate from reading load.');

  const unknownProfile = normalizeSourceQuestionAnalysis({
    analysis: {
      profile: {
        questionForm: 'unknown',
        cognitiveSkill: 'unknown',
        difficultyBand: 'unknown',
        readingLoad: 'unknown',
        calculationLoad: 'unknown',
        optionPattern: { optionStyle: 'unknown' }
      }
    },
    sourceQuestion: {
      subject: 'math',
      syllabusVersion: '2025',
      topicId: 4,
      promptText: 'Calculate the value of \\frac{2}{3} + 1.',
      options: [{ id: 'A', text: '5/3' }, { id: 'B', text: '2/3' }]
    }
  });
  assertEqual(unknownProfile.questionForm, 'formula_calculation', 'Source profile normalizer must infer question form when stored profile says unknown.');
  assertEqual(unknownProfile.cognitiveSkill, 'calculation', 'Source profile normalizer must infer cognitive skill when stored profile says unknown.');
  assert(unknownProfile.calculationLoad !== 'unknown', 'Source profile normalizer must infer calculation load when stored profile says unknown.');
  assert(unknownProfile.difficultyBand !== 'unknown', 'Source profile normalizer must not keep unknown difficulty when source signals allow inference.');

  const serviceSource = readFileSync(resolve(__dirname, '../backend/src/ai-questioning/ai-questioning.service.ts'), 'utf8');
  assert(
    serviceSource.includes("['unknown', 'unk', 'n/a', 'na', 'none', 'null', 'undefined', '未识别', '未知', '无'].includes(next.toLowerCase())"),
    'Style profile aggregation must not count placeholder unknown profile dimensions.'
  );
}

function testSourceQuestionImageDependencyStatus() {
  const textOnly = sourceQuestionImageDependencyStatus({
    question: {
      promptText: 'A car travels 20 m in 5 s. What is its speed?',
      options: [{ id: 'A', text: '4 m/s' }, { id: 'B', text: '25 m/s' }]
    }
  });
  assertEqual(textOnly.status, 'text_only', 'Plain text source questions should not be treated as visual-dependent.');

  const textualizedDiagram = sourceQuestionImageDependencyStatus({
    question: {
      promptText: 'The electrolysis setup is shown in the diagram: direct current power supply, inert electrodes, saturated brine, and gas collection at both electrodes. Which statement is correct?'
    },
    analysis: {
      stemPattern: { hasDiagram: true },
      styleNotes: ['diagram_textualized']
    }
  });
  assertEqual(textualizedDiagram.status, 'textualized_visual', 'Textualized diagrams should remain eligible for source profiling.');

  const missingVisual = sourceQuestionImageDependencyStatus({
    question: {
      promptText: 'The electric field lines are distributed as shown in the figure. Which relation between the forces is correct?'
    },
    analysis: {
      profile: { profileIssues: ['figure_dependent'], stemPattern: { hasDiagram: true } },
      styleNotes: ['figure_or_graph_context']
    }
  });
  assertEqual(missingVisual.status, 'missing_visual_dependency', 'Questions that rely on an unavailable figure should be excluded from profiling.');
  assertEqual(missingVisual.reasonCode, 'source_diagram_unavailable', 'Missing visual dependency should use a stable exclusion reason.');

  const describedGeometry = sourceQuestionImageDependencyStatus({
    question: {
      promptText: 'As shown in the figure, an object moves from A through B to C along two semicircles with radius R = 6 m, taking 4 s. What is the average velocity?'
    },
    analysis: {
      profile: { profileIssues: ['figure_dependent'], stemPattern: { hasDiagram: true } },
      styleNotes: ['diagram_context']
    }
  });
  assertEqual(describedGeometry.status, 'textualized_visual', 'Figure-style questions with enough numeric geometry in the stem should remain usable.');
}

