function testSyllabusImportRecoveryDraftContract() {
  const serviceSource = readFileSync(resolve(__dirname, '../backend/src/ai-questioning/ai-questioning.service.ts'), 'utf8');
  const controllerSource = readFileSync(resolve(__dirname, '../backend/src/ai-questioning/ai-questioning.controller.ts'), 'utf8');
  assert(
    serviceSource.includes('createSyllabusJsonImportRecoveryDraft'),
    'AI questioning service must expose a recovery draft creator for saved syllabus imports.'
  );
  assert(
    serviceSource.includes('sourceImportId: importRecord.id') && serviceSource.includes('sourceImportStatus: importRecord.status'),
    'Syllabus recovery drafts must preserve source import metadata in preview_summary.recovery.'
  );
  assert(
    serviceSource.includes('previewSyllabusJsonImport(payload)'),
    'Syllabus recovery drafts must recalculate preview impact against the current bank state.'
  );
  assert(
    controllerSource.includes("syllabus-imports/:id/recovery-draft") && controllerSource.includes("'recovery_draft'"),
    'AI questioning controller must expose an audited recovery-draft endpoint.'
  );
  assert(
    serviceSource.includes('createSyllabusJsonImportReversePlan') && serviceSource.includes("mode: 'dry_run'"),
    'AI questioning service must expose a dry-run reverse plan for applied syllabus imports.'
  );
  assert(
    serviceSource.includes('current_topic_drifted_after_apply') && serviceSource.includes('quality_attention_required'),
    'Syllabus reverse plans must surface drift blockers and quality-attention requirements.'
  );
  assert(
    controllerSource.includes("syllabus-imports/:id/reverse-plan") && controllerSource.includes("'reverse_plan'"),
    'AI questioning controller must expose an audited reverse-plan endpoint.'
  );
}

function makeOperationalInput(overrides = {}) {
  return {
    subject: 'math',
    blueprintCoverage: {
      summary: {
        publishedTopicCount: 10,
        coveredTopicCount: 10,
        missingTopicCount: 0,
        pausedBlueprintCount: 0
      }
    },
    topicHealth: {
      summary: {
        total: 10,
        missingBlueprintCount: 0,
        needsCandidateCount: 0,
        needsPublishCount: 0,
        needsQualityReviewCount: 0,
        healthyCount: 10
      }
    },
    generationQueue: {
      status: 'healthy',
      recommendedAction: 'monitor',
      summary: {
        queued: 0,
        running: 0,
        failed: 0,
        blocked: 0,
        staleRunning: 0
      }
    },
    syllabusGovernance: {
      summary: {
        staleCount: 0,
        unpublishedTopicCount: 0,
        pendingReviewCount: 0
      }
    },
    qualityGovernance: {
      summary: {
        needsReviewCount: 0,
        highSeverityCount: 0,
        sla: {
          escalationCount: 0,
          dueSoonCount: 0
        }
      }
    },
    ...overrides
  };
}

function testOperationalReadinessSummary() {
  const ready = buildAIQuestioningOperationalReadiness(makeOperationalInput());
  assertEqual(ready.status, 'ready', 'Fully healthy AI questioning operations should be ready.');
  assertEqual(ready.useCase, null, 'Readiness should expose null useCase when no workflow scope is selected.');
  assertEqual(ready.score, 100, 'Fully healthy AI questioning operations should score 100.');
  assertEqual(ready.nextAction, 'monitor', 'Ready operations should only require monitoring.');

  const blocked = buildAIQuestioningOperationalReadiness(makeOperationalInput({
    generationQueue: {
      status: 'blocked',
      recommendedAction: 'retry_failed',
      summary: { queued: 0, running: 1, failed: 2, blocked: 1, staleRunning: 1 }
    },
    syllabusGovernance: {
      summary: { staleCount: 3, unpublishedTopicCount: 0, pendingReviewCount: 2 }
    },
    qualityGovernance: {
      summary: { needsReviewCount: 4, highSeverityCount: 1, sla: { escalationCount: 2, dueSoonCount: 1 } }
    }
  }));
  assertEqual(blocked.status, 'blocked', 'Queue, syllabus, or SLA blockers must block operations.');
  assertEqual(blocked.nextAction, 'retry_or_clear_generation_queue', 'Readiness should surface the first blocking action.');
  assert(blocked.blockers.some((item) => item.key === 'generation_queue_blocked' && item.count === 2), 'Readiness must count queue blockers.');
  assert(blocked.blockers.some((item) => item.key === 'quality_sla_overdue' && item.count === 2), 'Readiness must count quality SLA blockers.');

  const warning = buildAIQuestioningOperationalReadiness(makeOperationalInput({
    blueprintCoverage: {
      summary: { publishedTopicCount: 10, coveredTopicCount: 8, missingTopicCount: 2, pausedBlueprintCount: 1 }
    },
    topicHealth: {
      summary: { total: 10, missingBlueprintCount: 2, needsCandidateCount: 3, needsPublishCount: 1, needsQualityReviewCount: 0, healthyCount: 4 }
    }
  }));
  assertEqual(warning.status, 'needs_attention', 'Non-blocking production gaps should require attention.');
  assert(warning.warnings.some((item) => item.key === 'missing_blueprints'), 'Readiness must expose blueprint coverage warnings.');
  assert(warning.score < 80, 'Readiness score should fall when topic coverage is weak.');

  const scoped = buildAIQuestioningOperationalReadiness(makeOperationalInput({ useCase: 'subject_practice' }));
  assertEqual(scoped.useCase, 'subject_practice', 'Readiness should preserve the selected AI-questioning workflow useCase.');
}

function testOperationalReadinessAuditSnapshot() {
  const readiness = buildAIQuestioningOperationalReadiness(makeOperationalInput({
    generationQueue: {
      status: 'blocked',
      recommendedAction: 'retry_failed',
      summary: { queued: 0, running: 0, failed: 1, blocked: 2, staleRunning: 0 }
    }
  }));
  const snapshot = buildAIQuestioningOperationalReadinessAuditSnapshot(readiness, {
    event: 'download_json',
    targetId: 'admin-ai-questioning-generation-governance',
    format: 'json'
  });
  assertEqual(snapshot.event, 'download_json', 'Readiness audit snapshot should preserve allowed event types.');
  assertEqual(snapshot.format, 'json', 'Readiness audit snapshot should preserve allowed export formats.');
  assertEqual(snapshot.status, 'blocked', 'Readiness audit snapshot should preserve current status.');
  assertEqual(snapshot.nextAction, 'retry_or_clear_generation_queue', 'Readiness audit snapshot should preserve next action.');
  assert(snapshot.blockers.some((item) => item.key === 'generation_queue_blocked' && item.count === 2), 'Readiness audit snapshot should include blocker counts.');
  assert(snapshot.warnings.some((item) => item.key === 'generation_queue_attention' && item.count === 1), 'Readiness audit snapshot should include warning counts.');

  const sanitized = buildAIQuestioningOperationalReadinessAuditSnapshot(readiness, {
    event: 'delete_everything',
    targetId: 123,
    format: 'xlsx'
  });
  assertEqual(sanitized.event, 'view_next_action', 'Unknown readiness audit event types should fall back to view_next_action.');
  assertEqual(sanitized.targetId, undefined, 'Readiness audit snapshot should not keep non-string target ids.');
  assertEqual(sanitized.format, undefined, 'Readiness audit snapshot should drop unsupported formats.');
}

function testVariantQualityEarlyWarning() {
  const reason = reviewReasonForMetric({
    attemptCount: 5,
    designedDifficulty: '中等',
    empiricalDifficulty: '挑战',
    correctRate: 0.2,
    unansweredRate: 0,
    isVariant: true
  });
  assertEqual(reason, 'weak_variant_effect', 'Weak remediation variants must enter quality review before the normal 20-attempt threshold.');

  const summary = qualitySummary({
    questionId: 8101,
    sourceQuestionId: null,
    generatedVariantOf: 8001,
    questionStatus: 'approved',
    subject: 'math',
    topicId: 3,
    designedDifficulty: '中等',
    empiricalDifficulty: '挑战',
    difficultyConfidence: 0.1,
    attemptCount: 5,
    correctRate: 0.2,
    medianSeconds: 42,
    unansweredRate: 0,
    markedRate: 0,
    optionSelectionStats: [],
    mostSelectedWrongOption: null,
    needsReview: true,
    reviewReason: 'weak_variant_effect',
    qualityGovernance: null,
    updatedAt: new Date('2026-06-11T00:00:00.000Z')
  });
  assertEqual(summary.severity, 'high', 'Weak variant effect must be treated as a high severity quality signal.');
  assertEqual(summary.recommendedAction, 'reduce_exposure', 'Weak variant effect should recommend reducing exposure until reviewed.');
  assert(summary.reasons.includes('variant_underperforming'), 'Weak variant summary must expose variant-underperforming reason.');
  assertEqual(summary.evidence.generatedVariantOf, 8001, 'Weak variant summary must expose the source question id.');
}

