function testQualityGovernanceSlaEscalation() {
  const now = new Date();
  const hoursAgo = (hours) => new Date(now.getTime() - hours * 60 * 60 * 1000).toISOString();
  const staleUnassignedSummary = qualitySummary({
    questionId: 9101,
    sourceQuestionId: null,
    generatedVariantOf: null,
    questionStatus: 'approved',
    subject: 'math',
    topicId: 3,
    designedDifficulty: '基础',
    empiricalDifficulty: '挑战',
    difficultyConfidence: 0.8,
    attemptCount: 30,
    correctRate: 0.1,
    medianSeconds: 42,
    unansweredRate: 0,
    markedRate: 0,
    optionSelectionStats: [],
    mostSelectedWrongOption: null,
    needsReview: true,
    reviewReason: 'correct_rate_too_low',
    qualityGovernance: null,
    updatedAt: new Date(hoursAgo(30))
  });
  const staleAssignedSummary = qualitySummary({
    questionId: 9102,
    sourceQuestionId: null,
    generatedVariantOf: null,
    questionStatus: 'approved',
    subject: 'math',
    topicId: 3,
    designedDifficulty: '基础',
    empiricalDifficulty: '挑战',
    difficultyConfidence: 0.8,
    attemptCount: 30,
    correctRate: 0.1,
    medianSeconds: 42,
    unansweredRate: 0,
    markedRate: 0,
    optionSelectionStats: [],
    mostSelectedWrongOption: null,
    needsReview: true,
    reviewReason: 'correct_rate_too_low',
    qualityGovernance: { status: 'assigned', assignedAt: hoursAgo(60), assignedTo: 2 },
    updatedAt: new Date(hoursAgo(60))
  });
  const dueSoonSummary = qualitySummary({
    questionId: 9103,
    sourceQuestionId: null,
    generatedVariantOf: null,
    questionStatus: 'approved',
    subject: 'math',
    topicId: 3,
    designedDifficulty: '基础',
    empiricalDifficulty: '挑战',
    difficultyConfidence: 0.8,
    attemptCount: 30,
    correctRate: 0.2,
    medianSeconds: 42,
    unansweredRate: 0,
    markedRate: 0,
    optionSelectionStats: [],
    mostSelectedWrongOption: null,
    needsReview: true,
    reviewReason: 'correct_rate_too_low',
    qualityGovernance: { status: 'assigned', assignedAt: hoursAgo(40), assignedTo: 2 },
    updatedAt: new Date(hoursAgo(40))
  });
  const governance = summarizeQualityGovernance([
    {
      questionId: 9101,
      generatedVariantOf: null,
      needsReview: true,
      reviewReason: 'correct_rate_too_low',
      qualitySummary: staleUnassignedSummary,
      qualityGovernance: null,
      updatedAt: hoursAgo(30)
    },
    {
      questionId: 9102,
      generatedVariantOf: null,
      needsReview: true,
      reviewReason: 'correct_rate_too_low',
      qualitySummary: staleAssignedSummary,
      qualityGovernance: { status: 'assigned', assignedAt: hoursAgo(60), assignedTo: 2 },
      updatedAt: hoursAgo(60)
    },
    {
      questionId: 9103,
      generatedVariantOf: null,
      needsReview: true,
      reviewReason: 'correct_rate_too_low',
      qualitySummary: dueSoonSummary,
      qualityGovernance: { status: 'assigned', assignedAt: hoursAgo(40), assignedTo: 2 },
      updatedAt: hoursAgo(40)
    }
  ]);

  assertEqual(governance.summary.sla.overdueUnassignedCount, 1, 'Quality SLA must count stale unassigned review items.');
  assertEqual(governance.summary.sla.overdueAssignedCount, 1, 'Quality SLA must count stale assigned review items.');
  assertEqual(governance.summary.sla.dueSoonCount, 1, 'Quality SLA must count soon-due assigned review items.');
  assertEqual(governance.summary.sla.escalationCount, 2, 'Quality SLA must count only overdue items as escalations.');
  assert(governance.summary.sla.sampleQuestionIds.includes(9101) && governance.summary.sla.sampleQuestionIds.includes(9102), 'Quality SLA must expose sample overdue question ids.');
  const unassignedBucket = governance.byAssignee.find((item) => item.assigneeId === null);
  const assigneeBucket = governance.byAssignee.find((item) => item.assigneeId === 2);
  assert(unassignedBucket && unassignedBucket.overdueCount === 1, 'Quality governance must group overdue unassigned review work.');
  assert(assigneeBucket && assigneeBucket.count === 2 && assigneeBucket.overdueCount === 1 && assigneeBucket.dueSoonCount === 1, 'Quality governance must group assigned reviewer workload and SLA pressure.');
}

