async function testPromptBuilderBoundsAndPrioritizesProductionFeedback() {
  const builder = new QuestionPromptBuilderService();
  const hardExperimentalInstruction = 'Generate a fresh hard experimental chemistry item using at least three evidence states, or at least four linked procedure operations with two interacting errors.';
  const mathQuestionPlanInstruction = 'For math QuestionPlan retries, treat every candidate_plan_math_* reason code as a hard structural correction before writing JSON.';
  const repairFeedback = {
    strategy: 'subject_practice_cell_guided_retry',
    repairMode: 'fresh_subject_practice_cell_candidate_after_recent_failures',
    productionRunId: 198,
    productionCellId: 593,
    reasonCodes: ['profile_difficulty_evidence_mismatch'],
    targetedInstructions: Array.from({ length: 12 }, (_, index) => (
      index === 10
        ? hardExperimentalInstruction
        : index === 11
          ? mathQuestionPlanInstruction
          : `generic retry instruction ${index} ${'x'.repeat(180)}`
    )),
    blockedPatterns: Array.from({ length: 10 }, (_, index) => (
      index === 9
        ? 'For a hard experimental chemistry target, do not use one direct hazard cue.'
        : `generic blocked pattern ${index} ${'y'.repeat(180)}`
    )),
    recentAcceptedScenarioHints: Array.from({ length: 8 }, (_, index) => `scenario ${index} ${'z'.repeat(180)}`)
  };
  const targetProfile = {
    questionForm: 'experimental_judgement',
    cognitiveSkill: 'multi_step_reasoning',
    difficultyBand: 'hard',
    readingLoad: 'medium',
    calculationLoad: 'none'
  };
  const prompt = builder.build(makeBlueprint({
    subject: 'chemistry',
    topicId: 653,
    topicCode: 'CHEM-LAB-001',
    topicModule: 'Laboratory',
    topicTitle: '实验室安全与仪器使用',
    difficultyRange: ['hard'],
    difficulty: 'hard',
    skill: 'multi_step_reasoning',
    constraints: {
      intendedUse: 'subject_practice',
      targetProfile,
      expansion: {
        generationMode: 'expand_candidates',
        repairFeedback
      }
    }
  }));
  const userPayload = JSON.parse(prompt.messages[1].content);
  const userPayloadText = JSON.stringify(userPayload);

  assert(prompt.messages[0].content.includes('at least three evidence states'), 'Hard experimental retry guidance must survive the bounded priority selection even when it appears late in stored feedback.');
  assert(prompt.messages[0].content.includes('candidate_plan_math_* reason code'), 'QuestionPlan retry guidance must survive the bounded priority selection even when it appears late in stored feedback.');
  assert(prompt.messages[0].content.includes('hard experimental chemistry target'), 'Hard experimental blocked patterns must outrank generic diversity narration.');
  assert(!userPayloadText.includes('generic retry instruction 0'), 'Raw targeted-instruction history must not be duplicated in the provider user payload.');
  assert(!userPayloadText.includes('generic blocked pattern 0'), 'Raw blocked-pattern history must not be duplicated in the provider user payload.');
  assertEqual(userPayload.expansion.repairFeedback.promptMemoryPolicy, 'bounded_system_instruction_is_authoritative_full_feedback_retained_in_metadata', 'Provider payload must declare the bounded feedback policy.');
  assertEqual(userPayload.expansion.repairFeedback.targetedInstructions, undefined, 'Provider payload must not duplicate full targetedInstructions.');
  assertEqual(prompt.metadata.constraints.expansion.repairFeedback.targetedInstructions.length, 12, 'Replay metadata must retain full production feedback.');
}

