function testBasicMathFunctionQuestionPlanRejectsMixedPropertyStack() {
  const plan = buildSubjectPracticeQuestionPlan({
    subject: 'math',
    topicId: 68,
    topicTitle: '函数的概念与性质',
    productionCellId: 13,
    targetDifficulty: 'basic',
    taskFamily: 'basic_function_direct_property'
  });
  assert(plan, 'Basic function production cell must build a QuestionPlan.');

  const mixedPropertyCandidate = {
    prompt: '已知二次函数 f(x)=x^2-2x-3。下列判断正确的是（ ）',
    options: [
      { id: 'A', text: '图象开口向下' },
      { id: 'B', text: '对称轴为 x=1' },
      { id: 'C', text: '最小值为 -3' },
      { id: 'D', text: '在 (0,+∞) 上单调递减' }
    ],
    explanation: '配方后可同时判断开口、对称轴、最小值和单调性。'
  };
  const mixedAdherence = subjectPracticeQuestionPlanAdherenceFor(plan, mixedPropertyCandidate);
  assert(!mixedAdherence.adheres, 'Basic function QuestionPlan must reject an option set that mixes several distinct function properties.');
  assert(
    mixedAdherence.failureCodes.includes('candidate_plan_math_function_property_stack_over_limit'),
    'Basic function property-stack rejection must expose an actionable failure code.'
  );

  const twoNamedPointsCandidate = {
    prompt: '已知函数 f(x)=2x-1，现有点 A(2,3) 与 B(3,5)。下列判断正确的是（ ）',
    options: [
      { id: 'A', text: 'A、B 都在图象上' },
      { id: 'B', text: '仅 A 在图象上' },
      { id: 'C', text: '仅 B 在图象上' },
      { id: 'D', text: 'A、B 都不在图象上' }
    ],
    explanation: '分别代入两个点判断。'
  };
  const twoNamedPointsAdherence = subjectPracticeQuestionPlanAdherenceFor(plan, twoNamedPointsCandidate);
  assert(twoNamedPointsAdherence.failureCodes.includes('candidate_plan_math_basic_function_multiple_named_points_forbidden'), 'Basic function plan must explicitly reject the observed two-named-point composite shape.');

  const parameterPointCandidate = {
    prompt: '已知函数 f(x)=2x-3。若点 P(a,a+1) 在图象上，其中 a 为实数，求 a 的值。',
    options: [
      { id: 'A', text: '2' },
      { id: 'B', text: '3' },
      { id: 'C', text: '4' },
      { id: 'D', text: '5' }
    ],
    explanation: '由 a+1=2a-3 解得 a=4。'
  };
  const parameterPointAdherence = subjectPracticeQuestionPlanAdherenceFor(plan, parameterPointCandidate);
  assert(parameterPointAdherence.failureCodes.includes('candidate_plan_math_parameter_inference_forbidden'), 'Basic function plan must explicitly reject a parameter point that requires solving for the parameter.');

  const solutionScaffoldCandidate = {
    prompt: '已知函数 f(x)=√(x-1)+1。判断点是否在图象上时，只需先检查横坐标是否在定义域内，再计算函数值。下列各点中，在图象上的是（ ）',
    options: [
      { id: 'A', text: '(1,1)' },
      { id: 'B', text: '(2,3)' },
      { id: 'C', text: '(0,1)' },
      { id: 'D', text: '(5,2)' }
    ],
    explanation: '代入可知 (1,1) 在图象上。'
  };
  const solutionScaffoldAdherence = subjectPracticeQuestionPlanAdherenceFor(plan, solutionScaffoldCandidate);
  assert(solutionScaffoldAdherence.failureCodes.includes('candidate_plan_math_basic_function_solution_scaffold_forbidden'), 'Basic function plan must keep worked-solution coaching out of the student-facing stem.');

  const singlePropertyCandidate = {
    prompt: '已知二次函数 f(x)=x^2-2x-3，其图象的对称轴是（ ）',
    options: [
      { id: 'A', text: 'x=-2' },
      { id: 'B', text: 'x=-1' },
      { id: 'C', text: 'x=1' },
      { id: 'D', text: 'x=2' }
    ],
    explanation: '由二次函数对称轴公式可得对称轴为 x=1。'
  };
  const singleAdherence = subjectPracticeQuestionPlanAdherenceFor(plan, singlePropertyCandidate);
  assert(singleAdherence.adheres, 'Basic function QuestionPlan must continue accepting a direct single-property item.');
}

function testBasicFunctionQuestionPlanFailureFeedbackStaysBasic() {
  const feedback = subjectPracticeProductionCellRetryFeedback({
    productionRunId: 1,
    productionCellId: 13,
    subject: 'math',
    topicTitle: '函数的概念与性质',
    reasonCodes: [
      'candidate_plan_math_function_property_evidence_missing',
      'candidate_plan_math_function_property_stack_over_limit',
      'candidate_plan_math_parameter_inference_forbidden',
      'candidate_plan_math_basic_function_solution_scaffold_forbidden'
    ],
    targetProfile: {
      questionForm: 'concept_check',
      cognitiveSkill: 'concept_identification',
      difficultyBand: 'basic',
      readingLoad: 'medium',
      calculationLoad: 'light'
    },
    rejectedCount: 2
  });
  const blockedText = feedback.blockedPatterns.join(' ');
  const targetedText = feedback.targetedInstructions.join(' ');
  assert(blockedText.includes('do not add a second named point, parameter inference, mixed property stack, or a two-step condition chain'), 'Basic function retry feedback must block both observed live failure shapes.');
  assert(blockedText.includes('do not introduce or solve for any parameter'), 'A forbidden parameter in a basic function plan must stay forbidden during retry.');
  assert(blockedText.includes('do not place worked-solution coaching'), 'Basic function retry feedback must remove worked-solution coaching from the student-facing stem.');
  assert(targetedText.includes('Use exactly one explicit function and ask exactly one direct'), 'Basic function retry feedback must request exactly one property/value target.');
  assert(targetedText.includes('keep all solving procedure and justification in the explanation field'), 'Basic function retry feedback must move procedure into the explanation field.');
  assert(!blockedText.includes('active plan requires multiple visible mathematical moves'), 'Basic function retry feedback must not inherit medium/hard multi-move requirements.');
  assert(!targetedText.includes('State the parameter, one explicit constraint'), 'Basic function retry feedback must not turn a forbidden parameter into a required parameter task.');
  const elementaryRotationFeedback = subjectPracticeProductionCellRetryFeedback({
    productionRunId: 1,
    productionCellId: 16,
    subject: 'math',
    topicTitle: '基本初等函数',
    reasonCodes: [],
    targetProfile: {
      questionForm: 'concept_check',
      cognitiveSkill: 'concept_identification',
      difficultyBand: 'basic',
      readingLoad: 'medium',
      calculationLoad: 'light'
    },
    rejectedCount: 0,
    currentCandidateCount: 2
  });
  assertEqual(elementaryRotationFeedback.questionPlanRotation?.functionClass, 'radical', 'The third basic elementary candidate slot must rotate to the radical function class.');
  assertEqual(elementaryRotationFeedback.questionPlanRotation?.propertyTarget, 'monotonicity', 'The third basic elementary candidate slot must rotate to the monotonicity target.');
  assert(elementaryRotationFeedback.targetedInstructions.some((line) => line.includes('Mandatory exact QuestionPlan scope rotation slot 3:')), 'Retry feedback must expose the selected rotation slot as a mandatory generation instruction.');
}

async function testReviewerEmitsProfileAlignment() {
  const generator = new QuestionGeneratorService();
  const reviewer = new QuestionReviewerService(new QuestionValidatorService(), new QuestionReviewerProviderService(disabledGateway()));
  const candidate = generator.generateFallbackCandidate(makeBlueprint());
  candidate.prompt = 'Given f(x)=2x+1, g(x)=x^2-3x, h(x)=f(x)+g(x), and k=h(4)-h(2), calculate the value of k for this function-composition calculation.';
  candidate.options = [
    { id: 'A', text: '10' },
    { id: 'B', text: '9' },
    { id: 'C', text: '11' },
    { id: 'D', text: '8' }
  ];
  candidate.correctAnswer = 'A';
  candidate.explanation = 'Combine h(x)=f(x)+g(x)=2x+1+x^2-3x=x^2-x+1. Then h(4)=16-4+1=13 and h(2)=4-2+1=3, so k=13-3=10. The correct answer is A.';
  candidate.optionMetadata = [
    { optionId: 'B', distractorIntent: 'calculation_error', misconceptionTags: ['calculation_error'] },
    { optionId: 'C', distractorIntent: 'substitution_error', misconceptionTags: ['substitution_error'] },
    { optionId: 'D', distractorIntent: 'condition_misread', misconceptionTags: ['condition_misread'] }
  ];

  const review = await reviewer.review(candidate, {
    subject: 'math',
    topicId: 7,
    topicTitle: 'Functions',
    syllabusVersion: '2026',
    topicStatus: 'published',
    styleProfile: { id: 1, confidence: 'medium', profile: {} },
    targetProfile: {
      questionForm: 'formula_calculation',
      cognitiveSkill: 'calculation',
      readingLoad: 'high',
      calculationLoad: 'heavy',
      distractorTypes: ['calculation_error']
    }
  });

  assert(review.profileAlignment, 'Reviewer must emit profile alignment metadata.');
  assertEqual(review.profileAlignment.status, 'passed', 'Aligned candidate should pass profile alignment.');
  assert(review.profileAlignment.score >= 75, 'Aligned profile score should be publishable.');
  assertEqual(review.profileAlignment.evidence.inferredCalculationLoad, 'heavy', 'Profile alignment should infer calculation load.');
}

