async function testReviewerKeepsLogarithmicDomainJudgementMedium() {
  const generator = new QuestionGeneratorService();
  const reviewer = new QuestionReviewerService(new QuestionValidatorService(), new QuestionReviewerProviderService(disabledGateway()));
  const candidate = generator.generateFallbackCandidate(makeBlueprint({
    subject: 'math',
    topicTitle: '函数的概念与性质',
    difficulty: 'medium'
  }));
  candidate.prompt = '在信号处理模型中，函数 f(x)=log_2(x^2-1)-log_2(x-1)，D 为其定义域。小华认为在 D 上 f(x)=log_2(x+1)，小丽认为 f(3)=2，小王认为 D=(1,+∞)。下列判断正确的是（ ）';
  candidate.options = [
    { id: 'A', text: '小华、小丽、小王均正确' },
    { id: 'B', text: '小华正确，小丽正确，小王错误' },
    { id: 'C', text: '小华错误，小丽正确，小王正确' },
    { id: 'D', text: '小华错误，小丽错误，小王正确' }
  ];
  candidate.correctAnswer = 'A';
  candidate.explanation = '因为 x^2-1=(x-1)(x+1)，且对数要求 x^2-1>0 与 x-1>0，所以 D=(1,+∞)。在 D 上 f(x)=log_2(x+1)，且 f(3)=log_2 4=2，因此三人均正确。';
  candidate.optionMetadata = [
    { optionId: 'B', distractorIntent: 'domain_condition_omitted', misconceptionTags: ['domain_condition_omitted'] },
    { optionId: 'C', distractorIntent: 'log_simplification_error', misconceptionTags: ['log_simplification_error'] },
    { optionId: 'D', distractorIntent: 'substitution_error', misconceptionTags: ['substitution_error'] }
  ];

  const review = await reviewer.review(candidate, {
    subject: 'math',
    intendedUse: 'subject_practice',
    topicId: 350,
    topicTitle: '函数的概念与性质',
    syllabusVersion: '2026',
    topicStatus: 'published',
    styleProfile: { id: 1, confidence: 'high', profile: {} },
    targetProfile: {
      questionForm: 'concept_judgement',
      cognitiveSkill: 'multi_step_reasoning',
      difficultyBand: 'medium',
      readingLoad: 'high',
      calculationLoad: 'medium',
      generationStrategy: {
        requiredStemPattern: 'concept_statement_judgement'
      }
    }
  });

  assert(review.profileAlignment, 'Logarithmic domain judgement should emit profile alignment metadata.');
  assertEqual(review.profileAlignment.evidence.inferredQuestionForm, 'concept_identification', 'Logarithmic domain judgement should remain concept-identification shaped.');
  assertEqual(review.profileAlignment.evidence.inferredCognitiveSkill, 'concept_identification', 'Concept judgement target should normalize multi-step wording to concept identification.');
  assertEqual(review.profileAlignment.evidence.inferredDifficultyBand, 'medium', 'Logarithmic domain equivalence judgement should be medium, not hard from repeated equality symbols.');
  assertEqual(review.profileAlignment.evidence.inferredCalculationLoad, 'medium', 'Logarithmic domain equivalence judgement should infer medium, not heavy, calculation load.');
  assert(review.profileAlignment.evidence.actualDifficultyReasons.includes('logarithmic_domain_equivalence_judgement_medium_cap'), 'Logarithmic domain judgement should leave an explicit medium-cap evidence reason.');
  assertEqual(review.profileAlignment.evidence.difficultyEvidencePatchVersion, 'math-logarithmic-domain-difficulty-evidence-patch-v1', 'Logarithmic domain judgement should expose the narrow math difficulty-evidence patch version without bumping all subjects.');
  assert(!review.profileAlignment.reasons.includes('difficulty_complexity_mismatch'), 'Medium logarithmic domain judgement should not warn on difficulty complexity.');
  assert(!review.profileAlignment.reasons.includes('calculation_load_band_mismatch'), 'Medium logarithmic domain judgement should not warn on calculation band.');
}

