async function testReviewerTreatsDirectFunctionPointMembershipAsBasic() {
  const reviewer = new QuestionReviewerService(new QuestionValidatorService(), new QuestionReviewerProviderService(disabledGateway()));
  const candidate = {
    subject: 'math',
    topicId: 68,
    blueprintId: 13,
    sourceType: 'ai',
    designedDifficulty: 'basic',
    questionType: 'single_choice',
    prompt: '已知函数 f(x)=√(2x-6)。由于被开方数不能为负，求定义域时需解不等式 2x-6≥0。判断点 (a,b) 是否在图象上，先检查 a 是否使根式有意义，再计算 b 是否等于 f(a)。下列各点中，位于该函数图象上的是（ ）',
    options: [
      { id: 'A', text: '（2，0）' },
      { id: 'B', text: '（5，2）' },
      { id: 'C', text: '（6，1）' },
      { id: 'D', text: '（3，1）' }
    ],
    correctAnswer: 'B',
    explanation: '由 2x-6≥0 得 x≥3。B 中 x=5≥3，且 f(5)=√4=2，故点（5，2）在图象上，B 正确。',
    knowledgeTags: ['函数', '根式函数', '图像上的点'],
    optionMetadata: [
      { optionId: 'B', distractorIntent: 'ignores radical domain', misconceptionTags: ['domain_error'] },
      { optionId: 'C', distractorIntent: 'omits the outside constant', misconceptionTags: ['substitution_error'] },
      { optionId: 'D', distractorIntent: 'miscalculates the square root', misconceptionTags: ['radical_error'] }
    ],
    syllabusVersion: '2025'
  };
  const review = await reviewer.review(candidate, {
    subject: 'math',
    intendedUse: 'subject_practice',
    topicId: 68,
    topicTitle: '函数的概念与性质',
    examScope: '理解函数定义域、函数值以及点与函数图像的关系。',
    syllabusVersion: '2025',
    topicStatus: 'published',
    styleProfile: { id: 1, confidence: 'high', profile: {} },
    targetProfile: {
      questionForm: 'concept_check',
      cognitiveSkill: 'multi_step_reasoning',
      difficultyBand: 'basic',
      readingLoad: 'medium',
      calculationLoad: 'light'
    }
  });

  assert(!review.issues.some((issue) => issue.code === 'answer_explanation_numeric_mismatch'), 'Coordinate-pair options must not be flattened into scalar numbers by the numeric consistency validator.');
  assertEqual(review.profileAlignment.evidence.inferredQuestionForm, 'concept_identification', 'Direct point-membership selection should retain the concept-check question form.');
  assertEqual(review.profileAlignment.evidence.inferredCognitiveSkill, 'concept_identification', 'Direct point-membership selection should align to the normalized concept skill.');
  assertEqual(review.profileAlignment.evidence.inferredDifficultyBand, 'basic', 'Direct substitution to check one point on a function graph should be basic.');
  assertEqual(review.profileAlignment.evidence.inferredCalculationLoad, 'light', 'Direct point substitution should provide light calculation evidence.');
  assertEqual(review.profileAlignment.evidence.inferredReadingLoad, 'medium', 'A direct radical-domain point check should stay at medium reading load even when the stem states the method.');
  assert(review.profileAlignment.evidence.actualDifficultyReasons.includes('direct_function_point_membership_basic_cap'), 'Direct function point membership should leave explicit basic-cap evidence.');
  assert(!review.profileAlignment.reasons.includes('difficulty_complexity_mismatch'), 'Direct point membership must not be promoted by the word graph alone.');
  assert(!review.profileAlignment.reasons.includes('calculation_load_mismatch'), 'Direct point substitution must satisfy a light-calculation target.');
}

