async function testValidatorDetectsEquivalentOptionText() {
  const generator = new QuestionGeneratorService();
  const validator = new QuestionValidatorService();
  const candidate = generator.generateFallbackCandidate(makeBlueprint());
  const broken = clone(candidate);
  broken.options = [
    { id: 'A', text: 'x = 5' },
    { id: 'B', text: 'x=5' },
    { id: 'C', text: 'x = -5' },
    { id: 'D', text: 'x = 0' }
  ];
  broken.explanation = 'The correct answer is A because x = 5 satisfies the condition.';

  const review = validator.review(broken);
  assertEqual(review.status, 'failed', 'Validator must fail option text that is equivalent after normalization.');
  assert(review.issues.some((issue) => issue.code === 'equivalent_option_text' && issue.severity === 'error'), 'Equivalent option text must be reported.');
  assert(review.dimensions.some((dimension) => dimension.key === 'option_mutual_exclusion' && dimension.status === 'failed'), 'Option mutual exclusion must fail for equivalent options.');

  const intervalBoundaries = clone(candidate);
  intervalBoundaries.options = [
    { id: 'A', text: '(1,+∞)' },
    { id: 'B', text: '[1,+∞)' },
    { id: 'C', text: '(-∞,1)' },
    { id: 'D', text: '(-∞,1]' }
  ];
  intervalBoundaries.correctAnswer = 'A';
  intervalBoundaries.explanation = 'The correct answer is A because the endpoint 1 is excluded.';
  const intervalReview = validator.review(intervalBoundaries);
  assert(!intervalReview.issues.some((issue) => issue.code === 'equivalent_option_text'), 'Interval endpoint brackets must remain semantically visible during option normalization.');

  const simpleLogarithm = clone(candidate);
  simpleLogarithm.subject = 'math';
  simpleLogarithm.prompt = '已知函数 f(x)=log₂(x-1)。下列判断中正确的是（ ）';
  simpleLogarithm.options = [
    { id: 'A', text: 'f(x) 的定义域为 (1,+∞)' },
    { id: 'B', text: 'f(x) 的定义域为 [1,+∞)' },
    { id: 'C', text: 'f(x) 在定义域内单调递减' },
    { id: 'D', text: 'f(3)=1' }
  ];
  simpleLogarithm.correctAnswer = 'A';
  simpleLogarithm.explanation = '正确答案为 A，因为真数 x-1 必须大于 0。';
  const logarithmReview = validator.review(simpleLogarithm);
  assert(logarithmReview.issues.some((issue) => issue.code === 'math_logarithm_true_distractor_conflict' && issue.severity === 'error'), 'A mathematically true point-value distractor for a simple logarithm must block publication.');
  assert(logarithmReview.dimensions.some((dimension) => dimension.key === 'domain_sanity' && dimension.status === 'failed'), 'The simple-logarithm true-distractor conflict must fail deterministic domain sanity.');
}

