async function testValidatorIgnoresEquilibriumQuotientRelation() {
  const validator = new QuestionValidatorService();
  const candidate = {
    subject: 'chemistry',
    topicId: 651,
    blueprintId: 44,
    sourceType: 'ai',
    designedDifficulty: 'medium',
    questionType: 'single_choice',
    prompt: '高温下，CaCO3(s) ⇌ CaO(s)+CO2(g) 在密闭容器中已达平衡。现向平衡体系中通入氦气：甲保持容器体积不变，乙保持总压强不变（允许体积改变），温度均不变。下列说法正确的是？',
    options: [
      { id: 'A', text: '甲、乙两种方式平衡均不移动' },
      { id: 'B', text: '甲不移动，乙平衡正移，CaCO3 的量减少' },
      { id: 'C', text: '甲平衡正移，乙不移动' },
      { id: 'D', text: '甲、乙均平衡正移，CaCO3 的量均减少' }
    ],
    correctAnswer: 'B',
    explanation: '恒容时 He 不参与反应，CO2 分压不变，Q=K，平衡不移动；恒压时体积增大使 CO2 分压下降，Q<K，平衡向生成 CO2 的正反应方向移动，故选 B。',
    knowledgeTags: ['化学平衡', '反应商', '惰性气体'],
    optionMetadata: [
      { optionId: 'A', distractorIntent: '忽略恒压通惰性气体会改变分压', misconceptionTags: ['pressure-condition-confusion'] },
      { optionId: 'C', distractorIntent: '误把恒容通惰性气体当作分压改变', misconceptionTags: ['constant-volume-confusion'] },
      { optionId: 'D', distractorIntent: '笼统认为通气都会改变平衡', misconceptionTags: ['inert-gas-overgeneralization'] }
    ],
    syllabusVersion: '2025'
  };

  const review = validator.review(candidate, { subject: 'chemistry', topicId: 651, topicTitle: '化学反应速率与平衡', syllabusVersion: '2025' });
  assert(!review.issues.some((issue) => issue.code === 'chemistry_unbalanced_equation'), 'Equilibrium quotient relation Q=K must not be treated as an unbalanced chemical equation.');

  const indexedEquilibriumConstantCandidate = {
    ...candidate,
    designedDifficulty: 'hard',
    prompt: '恒容密闭容器中反应 CO(g)+2H2(g)⇌CH3OH(g) ΔH<0 已达平衡。T1 时平衡常数 K1=4。现将温度降至 T2，测得该温度下 K2=8，平衡后再加入适量催化剂。下列说法正确的是',
    options: [
      { id: 'A', text: '降温瞬间 Q=K1=4<K2=8，平衡正向移动，CH3OH 产率增大；加入催化剂后平衡不移动，但正、逆反应速率均加快' },
      { id: 'B', text: '降温瞬间 Q=K1=4<K2=8，平衡正向移动；加入催化剂使平衡正向移动，产率进一步增大' },
      { id: 'C', text: '降温瞬间 Q=K2=8>K1=4，平衡逆向移动，CH3OH 产率减小；加入催化剂后平衡不移动' },
      { id: 'D', text: '降温瞬间 Q=K1=4，降温只使正、逆反应速率减小，平衡不移动；加入催化剂可使产率增大' }
    ],
    correctAnswer: 'A',
    explanation: '降温瞬间各物质浓度未变，故 Q=K1=4；而新温度下 K2=8，Q<K，平衡必正向移动，CH3OH 产率增大。催化剂只能同等加快正、逆反应速率，不改变平衡位置，故 A 正确。',
    knowledgeTags: ['勒夏特列原理', '反应商与平衡常数比较', '温度对平衡的影响', '催化剂对平衡的影响'],
    optionMetadata: [
      { optionId: 'B', distractorIntent: '误认为催化剂能改变平衡位置或提高产率', misconceptionTags: ['catalyst_shifts_equilibrium'] },
      { optionId: 'C', distractorIntent: '将降温后的反应商误取为新K并与旧K比较，方向判断反了', misconceptionTags: ['q_k_comparison_error'] },
      { optionId: 'D', distractorIntent: '混淆速率与平衡，忽略降温使K改变，并误信催化剂改变产率', misconceptionTags: ['rate_equilibrium_confusion'] }
    ]
  };
  const indexedReview = validator.review(indexedEquilibriumConstantCandidate, { subject: 'chemistry', topicId: 651, topicTitle: '化学反应速率与平衡', syllabusVersion: '2025' });
  assert(!indexedReview.issues.some((issue) => issue.code === 'chemistry_unbalanced_equation'), 'Indexed equilibrium constant relation Q=K1 must not be treated as an unbalanced chemical equation.');

  const molarityBoundaryCandidate = {
    ...candidate,
    prompt: '某温度下，CaCO3(s) ⇌ CaO(s)+CO2(g) 的平衡常数 K=c(CO2)=2.0 mol/L。现取两套已达平衡的密闭体系，甲保持体积不变充入氦气，乙保持总压不变充入氦气使体积变为原来的 2 倍，温度均不变。下列说法正确的是？',
    explanation: '甲中 CO2 的浓度仍为 2.0 mol/L，Q=K，平衡不移动；乙中体积增大导致 CO2 浓度下降，Q<K，平衡正向移动。'
  };
  const molarityBoundaryReview = validator.review(molarityBoundaryCandidate, { subject: 'chemistry', topicId: 651, topicTitle: '化学反应速率与平衡', syllabusVersion: '2025' });
  assert(!molarityBoundaryReview.issues.some((issue) => issue.code === 'chemistry_unbalanced_equation'), 'Molarity unit plus equilibrium relation must not create a false L=K unbalanced-equation issue.');
}

