async function testMisconceptionTagReplacementDedupesOptionMetadata() {
  const metadata = [
    { optionId: 'A', misconceptionTags: [] },
    { optionId: 'B', distractorIntent: 'Misses the condition.', misconceptionTags: ['condition-missing', 'other-gap', 'CONDITION-MISSING'] },
    { optionId: 'C', distractorIntent: 'Uses the wrong operation.', misconceptionTags: ['operation-error'] },
    { optionId: 'D', distractorIntent: 'Legacy slug.', misconceptionTags: ['math-7-condition-missing'] }
  ];
  const result = replaceMisconceptionTags(metadata, new Set(['condition-missing', 'math-7-condition-missing']), 'condition-gap');

  assertEqual(result.changed, true, 'Misconception replacement should report a changed metadata payload.');
  assertEqual(result.changedOptions, 2, 'Misconception replacement should count changed options.');
  assertEqual(result.optionMetadata[1].misconceptionTags.join('|'), 'condition-gap|other-gap', 'Duplicate source tags should collapse into one target tag.');
  assertEqual(result.optionMetadata[2].misconceptionTags.join('|'), 'operation-error', 'Unrelated misconception tags must be preserved.');
  assertEqual(result.optionMetadata[3].misconceptionTags.join('|'), 'condition-gap', 'Legacy source slugs should migrate to the target label.');
}

