    assertEqual(directResult.status, 'success', `Locally calibrated basic elementary-function plan should reach the mocked gateway successfully. Provider result: ${directResult.error ?? 'none'}`);
    assertEqual(capturedRequest?.thinking, 'disabled', 'Calibrated basic direct-property generation must avoid unnecessary hidden reasoning.');
    assertEqual(capturedRequest?.reasoningEffort, undefined, 'Calibrated basic direct-property generation must not send a reasoning-effort control while thinking is disabled.');
    assertEqual(capturedRequest?.maxTokens, 3000, 'Calibrated basic direct-property generation must use the compact output ceiling established after the 8,000-token truncation sample.');
    assertEqual(capturedRequest?.metadata?.reasoningPolicyVersion, 'question-generation-reasoning-effort-v3', 'Basic direct-property gateway metadata must expose the compact non-thinking policy.');
    assertEqual(capturedRequest?.metadata?.reasoningPolicyReason, 'basic_direct_property_uses_compact_non_thinking_generation', 'Basic direct-property gateway metadata must explain the compact non-thinking route.');
